export const wmsMapServerGetMap = async (params: WmsMapServerGetMapParams, options?: RequestInit, fetchFn?: typeof globalThis.fetch): Promise<wmsMapServerGetMapResponse> => {

  const res = await (fetchFn ?? fetch)(getWmsMapServerGetMapUrl(params),
  {
    ...options,
    method: 'GET'


  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.blob();
  const data: wmsMapServerGetMapResponse['data'] = body as wmsMapServerGetMapResponse['data']
  return { data, status: res.status, headers: res.headers } as wmsMapServerGetMapResponse
}
